import 'afm_validator.dart';

/// Type of IRIS QR code.
enum IrisQrType {
  /// Static QR, identifies a business by AFM (Tax ID).
  /// Format: `IRISTIN{AFM}`
  /// Used in physical stores. Customer enters amount in their banking app.
  tin,

  /// Dynamic QR, identifies a specific transaction by UUID.
  /// Format: `IRISCOM{UUID}`
  /// Generated by payment gateways (Cardlink, Nexi, etc.) for e-commerce.
  com,
}

/// Generates IRIS payment data strings.
///
/// The IRIS (Instant Retail Interbank Settlement) system is the Greek
/// instant payment standard managed by DIAS Interbanking Systems.
///
/// **Static QR (for physical stores):**
/// Encodes the payee's AFM in the format `IRISTIN{AFM}`.
/// Banking apps recognize this and let the customer enter the amount.
///
/// **Dynamic QR (for e-commerce):**
/// Encodes a transaction UUID in the format `IRISCOM{UUID}`.
/// Generated by payment gateways for a specific transaction with amount.
///
/// ```dart
/// // Static QR for a business
/// final data = IrisData.fromAfm('090000045');
/// print(data.qrString); // "IRISTIN090000045"
///
/// // Dynamic QR from a payment gateway
/// final tx = IrisData.fromTransactionId('52bb5e73-2ebd-4299-9ccf-e9714b9873fc');
/// print(tx.qrString); // "IRISCOM52bb5e73-2ebd-4299-9ccf-e9714b9873fc"
/// ```
class IrisData {
  /// The QR type.
  final IrisQrType type;

  /// The validated 9-digit AFM (for [IrisQrType.tin]).
  final String? afm;

  /// The transaction UUID (for [IrisQrType.com]).
  final String? transactionId;

  /// The IRIS QR code data string.
  String get qrString {
    switch (type) {
      case IrisQrType.tin:
        return 'IRISTIN$afm';
      case IrisQrType.com:
        return 'IRISCOM$transactionId';
    }
  }

  const IrisData._({
    required this.type,
    this.afm,
    this.transactionId,
  });

  /// Create a static IRIS QR from an AFM (Tax ID).
  ///
  /// Used for physical store QR codes displayed at checkout.
  /// The customer scans this and enters the amount in their banking app.
  ///
  /// Throws [ArgumentError] if the AFM is invalid.
  factory IrisData.fromAfm(String afm) {
    final cleaned = afm.replaceAll(RegExp(r'[\s\-]'), '');
    final result = AfmValidator.validate(cleaned);
    if (!result.isValid) {
      throw ArgumentError('Invalid AFM: ${result.message}');
    }
    return IrisData._(type: IrisQrType.tin, afm: cleaned);
  }

  /// Try to create a static IRIS QR from an AFM.
  ///
  /// Returns `null` if the AFM is invalid (no exception thrown).
  static IrisData? tryFromAfm(String afm) {
    final cleaned = afm.replaceAll(RegExp(r'[\s\-]'), '');
    if (AfmValidator.isValid(cleaned)) {
      return IrisData._(type: IrisQrType.tin, afm: cleaned);
    }
    return null;
  }

  /// Create a dynamic IRIS QR from a transaction UUID.
  ///
  /// Used for e-commerce transactions where the payment gateway
  /// generates a unique ID for each transaction (includes amount).
  ///
  /// Throws [ArgumentError] if the transaction ID is empty.
  factory IrisData.fromTransactionId(String transactionId) {
    if (transactionId.trim().isEmpty) {
      throw ArgumentError('Transaction ID cannot be empty');
    }
    return IrisData._(
      type: IrisQrType.com,
      transactionId: transactionId.trim(),
    );
  }

  /// Parse an IRIS QR string back into [IrisData].
  ///
  /// Supports both `IRISTIN{AFM}` and `IRISCOM{UUID}` formats.
  /// Returns `null` if the string is not a valid IRIS QR.
  static IrisData? parse(String qrString) {
    final trimmed = qrString.trim();
    if (trimmed.startsWith('IRISTIN')) {
      final afm = trimmed.substring(7);
      return tryFromAfm(afm);
    } else if (trimmed.startsWith('IRISCOM')) {
      final txId = trimmed.substring(7);
      if (txId.isNotEmpty) {
        return IrisData._(type: IrisQrType.com, transactionId: txId);
      }
    }
    return null;
  }

  @override
  String toString() => qrString;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is IrisData && type == other.type && qrString == other.qrString;

  @override
  int get hashCode => qrString.hashCode;
}
